return $input.all().map(item => {
  const messages = item.json.body.message.artifact.messages;

  const formatted = messages
    .filter(m => m.role === 'user' || m.role === 'bot')
    .map(m => ({
      role: m.role === 'bot' ? 'assistant' : 'user',
      content: m.message
    }));

  // Zusätzlich: Volltext-Transkript für Claude
  const transcript = messages
    .filter(m => m.role === 'user' || m.role === 'bot')
    .map(m => `${m.role === 'bot' ? 'Maja' : 'Mitarbeiter'}: ${m.message}`)
    .join('\n');

  return {
    json: {
      conversation: formatted,
      transcript,                                         // <-- neu
      call_id: item.json.body.message.call?.id,          // <-- neu
      duration: item.json.body.message.durationSeconds   // <-- neu
    }
  };
});

// ============================================================
// KI Agent parsen — robust
// ============================================================

const item = $input.first().json;

// 1) Output kann string oder bereits Objekt sein
let raw = item.output ?? item.text ?? item;
if (typeof raw === 'object') {
  return [{ json: normalize(raw) }];
}
raw = String(raw);

// 2) Markdown-Codefences entfernen (```json ... ``` oder ``` ... ```)
let cleaned = raw
  .replace(/^\s*```(?:json|JSON)?\s*\n?/g, '')
  .replace(/\n?```\s*$/g, '')
  .trim();

// 3) Ersten {...}-Block finden (greedy, ueber Newlines hinweg)
//    — fängt Faelle ab, in denen Hinweistext vor/nach dem JSON steht
const block = extractJsonBlock(cleaned);
if (!block) {
  throw new Error(
    'Kein JSON-Objekt im LLM-Output gefunden. Erste 200 Zeichen:\n' +
      cleaned.slice(0, 200),
  );
}

// 4) Typische LLM-Macken vor dem Parsen reparieren
const repaired = block
  // smart quotes -> straight quotes
  .replace(/[\u201C\u201D]/g, '"')
  .replace(/[\u2018\u2019]/g, "'")
  // trailing commas in objects/arrays
  .replace(/,(\s*[}\]])/g, '$1');

let parsed;
try {
  parsed = JSON.parse(repaired);
} catch (err) {
  throw new Error(
    `JSON.parse fehlgeschlagen: ${err.message}\n\nRepariert (erste 500 Zeichen):\n${repaired.slice(0, 500)}`,
  );
}

return [{ json: normalize(parsed) }];

// ============================================================
// Helpers
// ============================================================

// Findet den ersten ausbalancierten {...}-Block, ignoriert {}/[] in Strings
function extractJsonBlock(s) {
  const start = s.indexOf('{');
  if (start < 0) return null;

  let depth = 0;
  let inString = false;
  let escape = false;

  for (let i = start; i < s.length; i++) {
    const ch = s[i];

    if (escape) { escape = false; continue; }
    if (ch === '\\' && inString) { escape = true; continue; }
    if (ch === '"') { inString = !inString; continue; }
    if (inString) continue;

    if (ch === '{') depth++;
    else if (ch === '}') {
      depth--;
      if (depth === 0) return s.slice(start, i + 1);
    }
  }

  return null;
}

// Stellt sicher, dass alle erwarteten Felder existieren — verhindert,
// dass die Word-Generator-Node abschmiert wenn das LLM Felder weglaesst
function normalize(obj) {
  return {
    title: str(obj.title) || 'Unbenannte Anleitung',
    goal: str(obj.goal) || '',
    duration_minutes: Number.isFinite(+obj.duration_minutes) ? +obj.duration_minutes : 0,
    prerequisites: arr(obj.prerequisites).map(str).filter(Boolean),
    steps: arr(obj.steps).map((s, i) => ({
      step_number: Number.isFinite(+s?.step_number) ? +s.step_number : i + 1,
      title: str(s?.title) || `Schritt ${i + 1}`,
      description: str(s?.description) || '',
      tools: arr(s?.tools).map(str).filter(Boolean),
      pitfalls: arr(s?.pitfalls).map(str).filter(Boolean),
    })),
    edge_cases: arr(obj.edge_cases).map((e) => ({
      situation: str(e?.situation) || '',
      solution: str(e?.solution) || '',
    })),
    contacts: arr(obj.contacts).map(str).filter(Boolean),
    tags: arr(obj.tags).map(str).filter(Boolean),
  };
}

function str(v) {
  if (v == null) return '';
  if (typeof v === 'string') return v.trim();
  return String(v);
}

function arr(v) {
  return Array.isArray(v) ? v : [];
}

// =====================================================================
// How-To → DOCX (ein Code Node, kein externer Service)
// =====================================================================

function xmlEscape(s) {
  return String(s || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

function textToRuns(text, runProps) {
  if (!text) return '<w:r>' + runProps + '<w:t xml:space="preserve"></w:t></w:r>';
  return String(text).split(/\r?\n/).map(function(line, i) {
    if (i === 0) return '<w:r>' + runProps + '<w:t xml:space="preserve">' + xmlEscape(line) + '</w:t></w:r>';
    return '<w:br/><w:r>' + runProps + '<w:t xml:space="preserve">' + xmlEscape(line) + '</w:t></w:r>';
  }).join('');
}

function para(opts) {
  var text         = opts.text || '';
  var font         = opts.font || 'Arial';
  var size         = opts.size || 22;
  var color        = opts.color || '1a1a1a';
  var bold         = opts.bold || false;
  var italics      = opts.italics || false;
  var allCaps      = opts.allCaps || false;
  var alignment    = opts.alignment || null;
  var spacingBefore= opts.spacingBefore || 0;
  var spacingAfter = opts.spacingAfter !== undefined ? opts.spacingAfter : 120;
  var spacingLine  = opts.spacingLine || 0;
  var borderLeft   = opts.borderLeft || null;
  var borderTop    = opts.borderTop || null;
  var borderBottom = opts.borderBottom || null;
  var indentLeft   = opts.indentLeft || 0;

  var pPrParts = [];
  var borders = [];
  if (borderTop)    borders.push('<w:top    w:val="single" w:sz="' + borderTop.size    + '" w:space="' + (borderTop.space    || 1) + '" w:color="' + borderTop.color    + '"/>');
  if (borderBottom) borders.push('<w:bottom w:val="single" w:sz="' + borderBottom.size + '" w:space="' + (borderBottom.space || 1) + '" w:color="' + borderBottom.color + '"/>');
  if (borderLeft)   borders.push('<w:left   w:val="single" w:sz="' + borderLeft.size   + '" w:space="' + (borderLeft.space   || 4) + '" w:color="' + borderLeft.color   + '"/>');
  if (borders.length) pPrParts.push('<w:pBdr>' + borders.join('') + '</w:pBdr>');

  var spacingAtts = [];
  if (spacingBefore) spacingAtts.push('w:before="' + spacingBefore + '"');
  if (spacingAfter)  spacingAtts.push('w:after="'  + spacingAfter  + '"');
  if (spacingLine)   spacingAtts.push('w:line="'   + spacingLine   + '" w:lineRule="auto"');
  if (spacingAtts.length) pPrParts.push('<w:spacing ' + spacingAtts.join(' ') + '/>');

  if (indentLeft) pPrParts.push('<w:ind w:left="' + indentLeft + '"/>');
  if (alignment)  pPrParts.push('<w:jc w:val="' + alignment + '"/>');

  var rPrParts = [];
  rPrParts.push('<w:rFonts w:ascii="' + font + '" w:hAnsi="' + font + '" w:cs="' + font + '"/>');
  if (bold)    rPrParts.push('<w:b/>');
  if (italics) rPrParts.push('<w:i/>');
  if (allCaps) rPrParts.push('<w:caps/>');
  rPrParts.push('<w:color w:val="' + color + '"/>');
  rPrParts.push('<w:sz w:val="' + size + '"/>');
  rPrParts.push('<w:szCs w:val="' + size + '"/>');

  var runProps = '<w:rPr>' + rPrParts.join('') + '</w:rPr>';
  var pPr = pPrParts.length
    ? '<w:pPr>' + pPrParts.join('') + '<w:rPr>' + rPrParts.join('') + '</w:rPr></w:pPr>'
    : '';

  return '<w:p>' + pPr + textToRuns(text, runProps) + '</w:p>';
}

function bulletItem(text, font) {
  font = font || 'Arial';
  return '<w:p>' +
    '<w:pPr><w:spacing w:after="60"/><w:ind w:left="360" w:hanging="200"/></w:pPr>' +
    '<w:r><w:rPr>' +
      '<w:rFonts w:ascii="' + font + '" w:hAnsi="' + font + '"/>' +
      '<w:color w:val="555555"/><w:sz w:val="20"/>' +
    '</w:rPr>' +
    '<w:t xml:space="preserve">\u2013  ' + xmlEscape(text) + '</w:t></w:r>' +
    '</w:p>';
}

function sectionLabel(text) {
  return para({
    text: text,
    font: 'Arial', size: 17, bold: true, allCaps: true,
    color: '185FA5',
    spacingBefore: 280, spacingAfter: 80,
  });
}

function emptyPara() {
  return '<w:p><w:pPr><w:spacing w:after="0"/></w:pPr></w:p>';
}

function buildDocumentXml(data) {
  var today = new Date();
  var months = ['Januar','Februar','März','April','Mai','Juni','Juli','August','September','Oktober','November','Dezember'];
  var dateStr = today.getDate() + '. ' + months[today.getMonth()] + ' ' + today.getFullYear();

  var DARK  = '0c2340';
  var BLUE  = '185FA5';
  var GRAY  = '666666';

  var parts = [];

  // Titel
  parts.push(para({
    text: xmlEscape(data.title || 'How-To Anleitung'),
    font: 'Arial', size: 40, bold: true, color: DARK,
    spacingBefore: 200, spacingAfter: 80,
  }));

  // Meta
  var metaParts = [];
  if (data.duration_minutes) metaParts.push('Dauer: ca. ' + data.duration_minutes + ' Min.');
  metaParts.push('Erstellt: ' + dateStr);
  if (data.tags && data.tags.length) metaParts.push(data.tags.join(' \u00b7 '));
  parts.push(para({ text: metaParts.join('   |   '), font: 'Arial', size: 18, color: GRAY, spacingAfter: 320 }));

  // Ziel
  parts.push(para({
    text: 'ZIEL',
    font: 'Arial', size: 16, bold: true, allCaps: true, color: BLUE,
    spacingAfter: 40,
    borderLeft: { color: BLUE, size: 16, space: 12 },
    indentLeft: 200,
  }));
  parts.push(para({
    text: xmlEscape(data.goal || ''),
    font: 'Arial', size: 22, color: '222222',
    spacingAfter: 360, spacingLine: 340,
    borderLeft: { color: BLUE, size: 16, space: 12 },
    indentLeft: 200,
  }));

  // Voraussetzungen
  if (data.prerequisites && data.prerequisites.length) {
    parts.push(sectionLabel('Voraussetzungen'));
    data.prerequisites.forEach(function(p) { parts.push(bulletItem(p)); });
    parts.push(emptyPara());
  }

  // Schritte
  parts.push(sectionLabel('Schritte'));
  if (!data.steps || !data.steps.length) {
    parts.push(para({ text: 'Keine Schritte erfasst.', color: '999999', italics: true }));
  } else {
    data.steps.forEach(function(step, idx) {
      parts.push(para({
        text: (step.step_number || idx + 1) + '.  ' + xmlEscape(step.title || ''),
        font: 'Arial', size: 24, bold: true, color: DARK,
        spacingBefore: idx === 0 ? 0 : 240, spacingAfter: 60,
      }));
      if (step.description) {
        parts.push(para({
          text: xmlEscape(step.description),
          font: 'Arial', size: 22, color: '222222',
          spacingAfter: 80, spacingLine: 320, indentLeft: 280,
        }));
      }
      if (step.tools && step.tools.length) {
        parts.push(para({
          text: 'Tools: ' + step.tools.map(function(t) { return xmlEscape(t); }).join(', '),
          font: 'Arial', size: 18, color: GRAY, italics: true,
          spacingAfter: 60, indentLeft: 280,
        }));
      }
      if (step.pitfalls && step.pitfalls.length) {
        step.pitfalls.forEach(function(pf) {
          parts.push(para({
            text: 'Achtung: ' + xmlEscape(pf),
            font: 'Arial', size: 18, color: 'b45309',
            spacingAfter: 60, indentLeft: 280,
            borderLeft: { color: 'f0c040', size: 12, space: 10 },
          }));
        });
      }
    });
  }

  // Sonderfälle
  if (data.edge_cases && data.edge_cases.length) {
    parts.push(emptyPara());
    parts.push(sectionLabel('Sonderfälle'));
    data.edge_cases.forEach(function(ec) {
      parts.push(para({
        text: xmlEscape(ec.situation || ''),
        font: 'Arial', size: 22, bold: true, color: DARK,
        spacingAfter: 40, spacingBefore: 120,
      }));
      parts.push(para({
        text: xmlEscape(ec.solution || ''),
        font: 'Arial', size: 22, color: '444444',
        spacingAfter: 80, indentLeft: 280,
        borderLeft: { color: 'cccccc', size: 10, space: 10 },
      }));
    });
  }

  // Ansprechpartner
  if (data.contacts && data.contacts.length) {
    parts.push(emptyPara());
    parts.push(sectionLabel('Ansprechpartner'));
    data.contacts.forEach(function(c) { parts.push(bulletItem(c)); });
  }

  // Footer-Linie
  parts.push(para({
    text: '',
    spacingBefore: 480,
    borderTop: { color: 'cccccc', size: 6, space: 12 },
  }));
  parts.push(para({
    text: 'Erstellt mit dem Wissens-Agenten \u00b7 Interne Dokumentation \u00b7 Nicht zur Weitergabe',
    font: 'Arial', size: 16, italics: true, color: 'aaaaaa',
    spacingBefore: 80, spacingAfter: 0,
  }));

  var sectPr = '<w:sectPr>' +
    '<w:pgSz w:w="11906" w:h="16838"/>' +
    '<w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440" w:header="720" w:footer="720"/>' +
    '</w:sectPr>';

  return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
    '<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">' +
    '<w:body>' + parts.join('') + sectPr + '</w:body>' +
    '</w:document>';
}

// ---------------------------------------------------------------------
// ZIP-WRITER
// ---------------------------------------------------------------------

function crc32(buf) {
  if (!crc32._t) {
    crc32._t = new Uint32Array(256);
    for (var i = 0; i < 256; i++) {
      var c = i;
      for (var k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
      crc32._t[i] = c >>> 0;
    }
  }
  var crc = 0xFFFFFFFF;
  for (var i = 0; i < buf.length; i++) crc = (crc >>> 8) ^ crc32._t[(crc ^ buf[i]) & 0xFF];
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

function buildZip(files) {
  var now = new Date();
  var dt = ((now.getHours() & 0x1F) << 11) | ((now.getMinutes() & 0x3F) << 5) | ((Math.floor(now.getSeconds() / 2)) & 0x1F);
  var dd = (((now.getFullYear() - 1980) & 0x7F) << 9) | (((now.getMonth() + 1) & 0x0F) << 5) | (now.getDate() & 0x1F);

  var localChunks = [], centralChunks = [], offset = 0;

  files.forEach(function(f) {
    var name = Buffer.from(f.name, 'utf-8');
    var data = Buffer.isBuffer(f.data) ? f.data : Buffer.from(f.data, 'utf-8');
    var crc  = crc32(data);

    var local = Buffer.alloc(30 + name.length);
    var p = 0;
    local.writeUInt32LE(0x04034b50, p); p += 4;
    local.writeUInt16LE(20, p); p += 2;
    local.writeUInt16LE(0x0800, p); p += 2;
    local.writeUInt16LE(0, p); p += 2;
    local.writeUInt16LE(dt, p); p += 2;
    local.writeUInt16LE(dd, p); p += 2;
    local.writeUInt32LE(crc, p); p += 4;
    local.writeUInt32LE(data.length, p); p += 4;
    local.writeUInt32LE(data.length, p); p += 4;
    local.writeUInt16LE(name.length, p); p += 2;
    local.writeUInt16LE(0, p); p += 2;
    name.copy(local, p);
    localChunks.push(local);
    localChunks.push(data);

    var central = Buffer.alloc(46 + name.length);
    p = 0;
    central.writeUInt32LE(0x02014b50, p); p += 4;
    central.writeUInt16LE(20, p); p += 2;
    central.writeUInt16LE(20, p); p += 2;
    central.writeUInt16LE(0x0800, p); p += 2;
    central.writeUInt16LE(0, p); p += 2;
    central.writeUInt16LE(dt, p); p += 2;
    central.writeUInt16LE(dd, p); p += 2;
    central.writeUInt32LE(crc, p); p += 4;
    central.writeUInt32LE(data.length, p); p += 4;
    central.writeUInt32LE(data.length, p); p += 4;
    central.writeUInt16LE(name.length, p); p += 2;
    central.writeUInt16LE(0, p); p += 2;
    central.writeUInt16LE(0, p); p += 2;
    central.writeUInt16LE(0, p); p += 2;
    central.writeUInt16LE(0, p); p += 2;
    central.writeUInt32LE(0, p); p += 4;
    central.writeUInt32LE(offset, p); p += 4;
    name.copy(central, p);
    centralChunks.push(central);

    offset += local.length + data.length;
  });

  var dir  = Buffer.concat(centralChunks);
  var eocd = Buffer.alloc(22);
  var p = 0;
  eocd.writeUInt32LE(0x06054b50, p); p += 4;
  eocd.writeUInt16LE(0, p); p += 2;
  eocd.writeUInt16LE(0, p); p += 2;
  eocd.writeUInt16LE(files.length, p); p += 2;
  eocd.writeUInt16LE(files.length, p); p += 2;
  eocd.writeUInt32LE(dir.length, p); p += 4;
  eocd.writeUInt32LE(offset, p); p += 4;
  eocd.writeUInt16LE(0, p); p += 2;

  return Buffer.concat(localChunks.concat(centralChunks).concat([eocd]));
}

// ---------------------------------------------------------------------
// DOCX ZUSAMMENBAUEN
// ---------------------------------------------------------------------

function buildDocx(data) {
  var documentXml = buildDocumentXml(data);

  var contentTypes = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
    '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">' +
    '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>' +
    '<Default Extension="xml" ContentType="application/xml"/>' +
    '<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>' +
    '<Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/>' +
    '</Types>';

  var rels = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
    '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' +
    '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>' +
    '</Relationships>';

  var documentRels = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
    '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' +
    '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>' +
    '</Relationships>';

  var styles = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
    '<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">' +
    '<w:docDefaults>' +
    '<w:rPrDefault><w:rPr>' +
    '<w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial"/>' +
    '<w:sz w:val="22"/><w:szCs w:val="22"/>' +
    '</w:rPr></w:rPrDefault>' +
    '<w:pPrDefault><w:pPr>' +
    '<w:spacing w:after="120" w:line="300" w:lineRule="auto"/>' +
    '</w:pPr></w:pPrDefault>' +
    '</w:docDefaults>' +
    '<w:style w:type="paragraph" w:default="1" w:styleId="Normal">' +
    '<w:name w:val="Normal"/><w:qFormat/>' +
    '</w:style>' +
    '</w:styles>';

  return buildZip([
    { name: '[Content_Types].xml',          data: contentTypes },
    { name: '_rels/.rels',                  data: rels },
    { name: 'word/_rels/document.xml.rels', data: documentRels },
    { name: 'word/document.xml',            data: documentXml },
    { name: 'word/styles.xml',              data: styles },
  ]);
}

// ---------------------------------------------------------------------
// n8n INTEGRATION
// ---------------------------------------------------------------------

var input = $input.first().json;
var data = (typeof input.title === 'string') ? input : JSON.parse(input.output || '{}');

var docxBuffer = buildDocx(data);

var heute = new Date().toISOString().slice(0, 10);
var safeName = (data.title || 'how-to').replace(/[^a-z0-9]/gi, '_').slice(0, 40);
var filename = 'how_to_' + safeName + '_' + heute + '.docx';

var binaryData = await this.helpers.prepareBinaryData(
  docxBuffer,
  filename,
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
);

return [{ json: { filename: filename }, binary: { data: binaryData } }];
